CREATE FUNCTION public.kalzo_check_artist_media_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p text; BEGIN IF jsonb_typeof(NEW.reels) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Reels must be an array'; END IF; FOR p IN SELECT x FROM (SELECT NEW.photo_path x UNION ALL SELECT NEW.art_photo_path UNION ALL SELECT NEW.face_video_path UNION ALL SELECT jsonb_array_elements_text(NEW.reels)) paths LOOP IF coalesce(p,'')<>'' AND (split_part(p,'/',1)<>NEW.owner_id::text OR p ~ '(^|/)\.\.?(/|$)' OR p ~ '[%\\?#]' OR array_length(string_to_array(p,'/'),1)<2) THEN RAISE EXCEPTION 'Media must belong to the artist account'; END IF; END LOOP; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.kalzo_check_artist_media_owner() FROM PUBLIC; CREATE TRIGGER kalzo_artist_media_owner BEFORE INSERT OR UPDATE ON public.artist_profiles FOR EACH ROW EXECUTE FUNCTION public.kalzo_check_artist_media_owner();